head.script:
scwin.init = function() {
    wc.createWindow(titles[0], '', '', '아이튠즈', '', '', '', '');
    wc.createWindow(titles[1], '', '', '네이버', '', '', '', '');
    wc.createWindow(titles[2], '', '', '다음', '', '', '', '');
    wc.createWindow(titles[3], '', '', '네이버2', '', '', '', '');
}
scwin.test = function() {
    var iframes = document.getElementsByTagName('iframe');
    var iframeTitles = [];
    for (var i = 0, len = iframes.length; i < len; i++) {
        iframeTitles.push(iframes[i].title);
    }
    for (var i = 0, len = iframeTitles.length; i < len; i++) {
        if (iframeTitles[i] != titles[i]) {
            isSame = false;
        }
    }
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("assert", "isSame == true", "true");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.checkVal1 = function() {
    return isSame == true;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 개발자도구 (F12) 를 실행한다.
    //1. Run the Developer Tool (F12) in your browser.
    //Test step 2. "iframe" 을 검색한다.
    //2. Search for "iframe".
    //Verify 2. iFrame 에 title 속성이 추가되어 title 이 표시된다.
    //2. The title attribute is added to the iFrame to display the title.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wc_subWindow0_iframe').getAttribute('title')", "itunes");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.titles = ['itunes', 'naver', 'daum', 'naver2'];
    window.isSame = true;
    scwin.init();
    //test();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 05-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
